-- =============================================================================
-- Figure data: the four figures from the pairs-trading article.
--
-- Generated once from the retired `public/figures/*.json` payloads, and now
-- the initial load for a fresh database: `supabase db reset` applies it after
-- seed.sql, and it is what to run against a new environment before the
-- content rewrite in supabase/snippets/2026-07-26-charts-to-database.sql.
--
-- Not a mirror of production. Once a figure is edited at /admin the database
-- moves ahead of this file, which stays as version 1 of each dataset. Editing
-- here is fine; it is ordinary SQL now, with no generator behind it.
--
-- Safe to re-run: datasets and charts upsert, and version 1 of each dataset is
-- corrected in place. Versions created by an import are numbered above 1 and
-- are never touched.
-- =============================================================================

insert into public.datasets (slug, name, description, source, status)
values ('pairs-liquidity-ladder', 'Liquidity ladder', 'Gross and net PnL bucketed by the less-liquid leg''s 1-year volume rank.', 'Kraken spot, 1-min bars, Dec 2024 – Dec 2025', 'published')
on conflict (slug) do update set
  name = excluded.name, description = excluded.description,
  source = excluded.source, status = excluded.status;

insert into public.dataset_versions (dataset_id, version, columns, data, row_count, checksum, source_name)
select d.id, 1, '[{"key":"rank_bucket","label":"Volume rank","type":"string"},{"key":"gross_pnl","label":"Gross PnL","type":"number","format":"usd"},{"key":"net_pnl_2bps","label":"Net PnL at 2 bps","type":"number","format":"usd"},{"key":"trades","label":"Trades","type":"integer"}]'::jsonb, '{"rank_bucket":["2–10 (majors)","11-15","16-25","26-50","51–100 (illiquid tail)"],"gross_pnl":[-3.84,-6.49,112.31,489.15,1823.32],"net_pnl_2bps":[-8.25,-13.8,87.1,383.02,1448.26],"trades":[175,344,1771,7261,28690]}'::jsonb, 5, '6921800f62b1db8c76e6cd8c987f2570cd9473e2eae4ec6d0906e140b4780d0d', 'build-figure-data.py'
from public.datasets d where d.slug = 'pairs-liquidity-ladder'
on conflict (dataset_id, version) do update set
  columns = excluded.columns, data = excluded.data,
  row_count = excluded.row_count, checksum = excluded.checksum,
  source_name = excluded.source_name;

update public.datasets set current_version_id = (
  select v.id from public.dataset_versions v
  where v.dataset_id = datasets.id order by v.version desc limit 1
) where slug = 'pairs-liquidity-ladder';

insert into public.datasets (slug, name, description, source, status)
values ('pairs-crossover-error', 'Crossover: relative error', 'Relative error of each F''/F representation against the quadrature reference.', 'verify_math.py quadrature reference, a = 1.5', 'published')
on conflict (slug) do update set
  name = excluded.name, description = excluded.description,
  source = excluded.source, status = excluded.status;

