-order correction"],"range":[[1,0],[1,0],[1,0],[5,3]]},"legend":null},"tooltip":[{"field":"series","type":"nominal","title":"Representation"},{"field":"beta","type":"quantitative","title":"beta"},{"field":"rel_error","type":"quantitative","title":"Relative error","format":".2e"}]}},{"data":{"name":"labels"},"mark":{"type":"text","dy":-8,"fontWeight":500,"fontSize":10},"encoding":{"x":{"field":"beta","type":"quantitative"},"y":{"field":"rel_error","type":"quantitative"},"text":{"field":"label"}}},{"data":{"name":"main"},"mark":{"type":"point","size":120,"opacity":0},"encoding":{"x":{"field":"beta","type":"quantitative"},"y":{"field":"rel_error","type":"quantitative"},"tooltip":[{"field":"series","type":"nominal","title":"Representation"},{"field":"beta","type":"quantitative","title":"beta"},{"field":"rel_error","type":"quantitative","title":"Relative error","format":".2e"}]}}]}'::jsonb, '{"main":{"slug":"pairs-crossover-error","version":null},"labels":{"slug":"pairs-crossover-labels","version":null},"annotations":{"slug":"pairs-crossover-annotations","version":null}}'::jsonb, false, 'published')
